Redis Pub/Sub Event Bus for Real-time Synchronization
======================================================

Provides real-time event publishing and subscription:
- Knowledge updates
- Task assignments
- Agent status changes
- System events
"""

import json
import time
import redis
import threading
from typing import Dict, List, Optional, Callable, Any
from enum import Enum

from .config import Config


class EventType(str, Enum):
    """Event type enumeration."""
    KNOWLEDGE_CREATED = "knowledge.created"
    KNOWLEDGE_UPDATED = "knowledge.updated"
    KNOWLEDGE_DELETED = "knowledge.deleted"
    TASK_SUBMITTED = "task.submitted"
    TASK_ASSIGNED = "task.assigned"
    TASK_STARTED = "task.started"
    TASK_COMPLETED = "task.completed"
    TASK_FAILED = "task.failed"
    AGENT_REGISTERED = "agent.registered"
    AGENT_ONLINE = "agent.online"
    AGENT_OFFLINE = "agent.offline"
    AGENT_HEARTBEAT = "agent.heartbeat"
    SYSTEM_STARTUP = "system.startup"
    SYSTEM_SHUTDOWN = "system.shutdown"
    SYSTEM_ERROR = "system.error"


class Event:
    """Event representation."""

    def __init__(
        self,
        event_type: EventType,
        data: Dict,
        source: Optional[str] = None,
        timestamp: Optional[float] = None
    ):
        self.event_type = event_type
        self.data = data
        self.source = source or "orchestrator"
        self.timestamp = timestamp or time.time()

    def to_dict(self) -> Dict:
        """Convert event to dictionary."""
        return {
            "event_type": self.event_type,
            "data": self.data,
            "source": self.source,
            "timestamp": self.timestamp
        }

    def to_json(self) -> str:
        """Convert event to JSON string."""
        return json.dumps(self.to_dict())

    @classmethod
    def from_dict(cls, data: Dict) -> "Event":
        """Create event from dictionary."""
        return cls(
            event_type=data["event_type"],
            data=data["data"],
            source=data.get("source"),
            timestamp=data.get("timestamp")
        )

    @classmethod
    def from_json(cls, json_str: str) -> "Event":
        """Create event from JSON string."""
        return cls.from_dict(json.loads(json_str))


class EventBus:
    """Redis-based event bus for real-time synchronization."""

    def __init__(self):
        """Initialize event bus."""
        self.redis = redis.from_url(Config.get_redis_url(), decode_responses=True)
        self.pubsub = self.redis.pubsub()
        self.subscribers: Dict[str, List[Callable]] = {}
        self.running = False
        self.listener_thread = None

    def publish(self, event: Event):
        """
        Publish an event to the appropriate channel.

        Args:
            event: Event to publish
        """
        # Determine channel based on event type
        channel = self._get_channel_for_event(event.event_type)

        # Publish to Redis
        self.redis.publish(channel, event.to_json())

    def publish_event(
        self,
        event_type: EventType,
        data: Dict,
        source: Optional[str] = None
    ):
        """
        Publish an event (convenience method).

        Args:
            event_type: Type of event
            data: Event data
            source: Event source
        """
        event = Event(event_type, data, source)
        self.publish(event)

    def subscribe(self, event_type: EventType, callback: Callable[[Event], None]):
        """
        Subscribe to an event type.

        Args:
            event_type: Event type to subscribe to
            callback: Callback function to call when event is received
        """
        channel = self._get_channel_for_event(event_type)

        if channel not in self.subscribers:
            self.subscribers[channel] = []
            self.pubsub.subscribe(channel)

        self.subscribers[channel].append(callback)

    def subscribe_pattern(self, pattern: str, callback: Callable[[Event], None]):
        """
        Subscribe to events matching a pattern.

        Args:
            pattern: Channel pattern (e.g., "hermes:*")
            callback: Callback function
        """
        if pattern not in self.subscribers:
            self.subscribers[pattern] = []
            self.pubsub.psubscribe(pattern)

        self.subscribers[pattern].append(callback)

    def unsubscribe(self, event_type: EventType):
        """
        Unsubscribe from an event type.

        Args:
            event_type: Event type to unsubscribe from
        """
        channel = self._get_channel_for_event(event_type)

        if channel in self.subscribers:
            self.pubsub.unsubscribe(channel)
            del self.subscribers[channel]

    def start(self):
        """Start listening for events."""
        if self.running:
            return

        self.running = True
        self.listener_thread = threading.Thread(target=self._listen, daemon=True)
        self.listener_thread.start()

    def stop(self):
        """Stop listening for events."""
        self.running = False
        if self.listener_thread:
            self.listener_thread.join(timeout=5)

    def _listen(self):
        """Listen for events (runs in separate thread)."""
        while self.running:
            try:
                message = self.pubsub.get_message(timeout=1.0)
                if message and message["type"] in ["message", "pmessage"]:
                    self._handle_message(message)
            except Exception as e:
                print(f"Error in event listener: {e}")

    def _handle_message(self, message: Dict):
        """Handle incoming message."""
        try:
            # Get channel
            channel = message.get("channel") or message.get("pattern")
            if not channel:
                return

            # Parse event
            event = Event.from_json(message["data"])

            # Call subscribers
            if channel in self.subscribers:
                for callback in self.subscribers[channel]:
                    try:
                        callback(event)
                    except Exception as e:
                        print(f"Error in event callback: {e}")

        except Exception as e:
            print(f"Error handling message: {e}")

    def _get_channel_for_event(self, event_type: EventType) -> str:
        """Get Redis channel for event type."""
        if event_type.startswith("knowledge."):
            return Config.CHANNEL_KNOWLEDGE_UPDATES
        elif event_type.startswith("task."):
            return Config.CHANNEL_TASK_ASSIGNMENTS
        elif event_type.startswith("agent."):
            return Config.CHANNEL_AGENT_STATUS
        elif event_type.startswith("system."):
            return Config.CHANNEL_SYSTEM_EVENTS
        else:
            return Config.CHANNEL_SYSTEM_EVENTS

    def get_stats(self) -> Dict:
        """Get event bus statistics."""
        return {
            "running": self.running,
            "subscribed_channels": list(self.subscribers.keys()),
            "subscriber_count": sum(len(subs) for subs in self.subscribers.values())
        }


class KnowledgeEventPublisher:
    """Publisher for knowledge-related events."""

    def __init__(self, event_bus: EventBus):
        self.event_bus = event_bus

    def publish_knowledge_created(self, knowledge_id: int, data: Dict):
        """Publish knowledge created event."""
        self.event_bus.publish_event(
            EventType.KNOWLEDGE_CREATED,
            {"knowledge_id": knowledge_id, **data}
        )

    def publish_knowledge_updated(self, knowledge_id: int, data: Dict):
        """Publish knowledge updated event."""
        self.event_bus.publish_event(
            EventType.KNOWLEDGE_UPDATED,
            {"knowledge_id": knowledge_id, **data}
        )

    def publish_knowledge_deleted(self, knowledge_id: int):
        """Publish knowledge deleted event."""
        self.event_bus.publish_event(
            EventType.KNOWLEDGE_DELETED,
            {"knowledge_id": knowledge_id}
        )


