FastAPI REST API + WebSocket for Hermes Orchestrator
=====================================================

Provides HTTP endpoints for:
- Task submission and management
- Agent registration and monitoring
- Knowledge pool access
- System health checks
- WebSocket for real-time events
"""

from fastapi import FastAPI, HTTPException, WebSocket, WebSocketDisconnect, Query
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field
from typing import Dict, List, Optional, Any, Set
import uvicorn
import asyncio
import json
import time

from orchestrator import (
    Orchestrator,
    TaskPriority,
    TaskStatus,
    AgentStatus,
    EventType
)


# Pydantic models for request/response
class TaskSubmitRequest(BaseModel):
    task_type: str = Field(..., description="Type of task")
    description: str = Field(..., description="Task description")
    input_data: Optional[Dict] = Field(None, description="Input data")
    priority: str = Field("normal", description="Priority: low, normal, high, critical")
    required_capability: Optional[str] = Field(None, description="Required agent capability")
    metadata: Optional[Dict] = Field(None, description="Additional metadata")


class TaskSubmitResponse(BaseModel):
    task_id: str
    status: str
    message: str


class AgentRegisterRequest(BaseModel):
    agent_id: str = Field(..., description="Unique agent ID")
    agent_name: str = Field(..., description="Agent name")
    capabilities: List[str] = Field(..., description="Agent capabilities")
    metadata: Optional[Dict] = Field(None, description="Additional metadata")


class AgentHeartbeatRequest(BaseModel):
    agent_id: str = Field(..., description="Agent ID")
    status: Optional[str] = Field(None, description="Agent status")


class TaskCompleteRequest(BaseModel):
    task_id: str = Field(..., description="Task ID")
    result: Optional[Dict] = Field(None, description="Task result")
    error: Optional[str] = Field(None, description="Error message if failed")


# Initialize FastAPI app
app = FastAPI(
    title="Hermes Orchestrator API",
    description="Multi-Agent Orchestration System with Real-time Events",
    version="1.0.0"
)

# CORS middleware
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Initialize orchestrator
orchestrator = Orchestrator()

# WebSocket connection manager
class ConnectionManager:
    def __init__(self):
        self.active_connections: Set[WebSocket] = set()

    async def connect(self, websocket: WebSocket):
        await websocket.accept()
        self.active_connections.add(websocket)

    def disconnect(self, websocket: WebSocket):
        self.active_connections.discard(websocket)

    async def broadcast(self, message: str):
        for connection in self.active_connections.copy():
            try:
                await connection.send_text(message)
            except Exception:
                self.active_connections.discard(connection)

manager = ConnectionManager()


# Event handler for broadcasting
def broadcast_event(event):
    """Broadcast event to all WebSocket clients."""
    asyncio.create_task(manager.broadcast(json.dumps({
        "event_type": event.event_type,
        "data": event.data,
        "source": event.source,
        "timestamp": event.timestamp
    })))


# Startup event
@app.on_event("startup")
async def startup_event():
    """Start orchestrator and event bus."""
    orchestrator.event_bus.start()
    orchestrator.knowledge_sync.start()

    # Subscribe to all events for WebSocket broadcasting
    orchestrator.event_bus.subscribe_pattern("hermes:*", broadcast_event)

    print("✅ Orchestrator API started")
    print("✅ Event bus started")
    print("✅ Knowledge sync started")


# Shutdown event
@app.on_event("shutdown")
async def shutdown_event():
    """Stop orchestrator and event bus."""
    orchestrator.event_bus.stop()
    print("✅ Orchestrator API stopped")


# Health check endpoint
@app.get("/health")
async def health_check():
    """System health check."""
    health = orchestrator.health_monitor.health_check()
    return health.to_dict()


# System status endpoint
@app.get("/status")
async def system_status():
    """Get overall system status."""
    return orchestrator.get_system_status()


# Task endpoints
@app.post("/tasks", response_model=TaskSubmitResponse)
async def submit_task(request: TaskSubmitRequest):
    """Submit a new task."""
    try:
        # Map priority string to enum
        priority_map = {
            "low": TaskPriority.LOW,
            "normal": TaskPriority.NORMAL,
            "high": TaskPriority.HIGH,
            "critical": TaskPriority.CRITICAL
        }
        priority = priority_map.get(request.priority.lower(), TaskPriority.NORMAL)

        task_id = orchestrator.submit_task(
            task_type=request.task_type,
            description=request.description,
            input_data=request.input_data,
            priority=priority,
            required_capability=request.required_capability,
            metadata=request.metadata
        )

        return TaskSubmitResponse(
            task_id=task_id,
            status="submitted",
            message="Task submitted successfully"
        )

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/tasks/{task_id}")
async def get_task(task_id: str):
    """Get task details."""
    task = orchestrator.get_task_status(task_id)
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    return task


@app.get("/tasks")
async def list_tasks(
    status: Optional[str] = Query(None, description="Filter by status"),
    limit: int = Query(50, description="Maximum number of tasks")
):
    """List tasks."""
    status_enum = None
    if status:
        try:
            status_enum = TaskStatus(status)
        except ValueError:
            raise HTTPException(status_code=400, detail=f"Invalid status: {status}")

    tasks = orchestrator.list_tasks(status=status_enum, limit=limit)
    return {"tasks": tasks, "count": len(tasks)}


@app.post("/tasks/{task_id}/complete")
async def complete_task(task_id: str, request: TaskCompleteRequest):
    """Mark task as completed or failed."""
    try:
        if request.error:
            success = orchestrator.complete_task(task_id, error=request.error)
            status = "failed"
        else:
            success = orchestrator.complete_task(task_id, result=request.result)
            status = "completed"

        if not success:
            raise HTTPException(status_code=404, detail="Task not found or cannot be completed")

        return {"task_id": task_id, "status": status, "message": f"Task {status}"}

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


# Agent endpoints
@app.post("/agents/register")
async def register_agent(request: AgentRegisterRequest):
    """Register a new agent."""
    try:
        success = orchestrator.register_agent(
            agent_id=request.agent_id,
            agent_name=request.agent_name,
            capabilities=request.capabilities,
            metadata=request.metadata
        )

        if not success:
            raise HTTPException(status_code=400, detail="Agent already registered")

        return {
            "agent_id": request.agent_id,
            "status": "registered",
            "message": "Agent registered successfully"
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/agents/heartbeat")
async def agent_heartbeat(request: AgentHeartbeatRequest):
    """Update agent heartbeat."""
    try:
        status_enum = None
        if request.status:
            try:
                status_enum = AgentStatus(request.status)
            except ValueError:
                raise HTTPException(status_code=400, detail=f"Invalid status: {request.status}")

        success = orchestrator.agent_heartbeat(request.agent_id, status_enum)

        if not success:
            raise HTTPException(status_code=404, detail="Agent not found")

        return {
            "agent_id": request.agent_id,
            "status": "ok",
            "message": "Heartbeat received"
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/agents")
async def list_agents(
    status: Optional[str] = Query(None, description="Filter by status"),
    capability: Optional[str] = Query(None, description="Filter by capability")
):
    """List agents."""
    status_enum = None
    if status:
        try:
            status_enum = AgentStatus(status)
        except ValueError:
            raise HTTPException(status_code=400, detail=f"Invalid status: {status}")

    agents = orchestrator.list_agents(status=status_enum, capability=capability)
    return {"agents": agents, "count": len(agents)}


@app.get("/agents/{agent_id}")
async def get_agent(agent_id: str):
    """Get agent details."""
    agent = orchestrator.get_agent_info(agent_id)
    if not agent:
        raise HTTPException(status_code=404, detail="Agent not found")
    return agent


# Knowledge endpoints
@app.get("/knowledge")
async def list_knowledge(
    limit: int = Query(50, description="Maximum number of entries")
):
    """List knowledge entries from shared memory."""
    entries = orchestrator.knowledge_sync.list_knowledge_entries(limit=limit)
    return {"entries": entries, "count": len(entries)}


@app.get("/knowledge/{knowledge_id}")
async def get_knowledge(knowledge_id: int):
    """Get specific knowledge entry."""
    entry = orchestrator.knowledge_sync.get_knowledge_entry(knowledge_id)
    if not entry:
        raise HTTPException(status_code=404, detail="Knowledge entry not found")
    return entry


@app.get("/knowledge/search")
async def search_knowledge(
    q: str = Query(..., description="Search query"),
    limit: int = Query(10, description="Maximum number of results")
):
    """Search knowledge entries."""
    results = orchestrator.knowledge_sync.search_knowledge(q, limit=limit)
    return {"results": results, "count": len(results)}


# WebSocket endpoint for real-time events
@app.websocket("/ws")
async def websocket_endpoint(websocket: WebSocket):
    """WebSocket endpoint for real-time event streaming."""
    await manager.connect(websocket)

    try:
        # Send welcome message
        await websocket.send_text(json.dumps({
            "event_type": "connection.established",
            "data": {"message": "Connected to Hermes Orchestrator"},
            "timestamp": time.time()
        }))

        # Keep connection alive
        while True:
            # Wait for client messages (ping/pong)
            data = await websocket.receive_text()

            # Echo back for ping/pong
            if data == "ping":
                await websocket.send_text(json.dumps({
                    "event_type": "pong",
                    "timestamp": time.time()
                }))

    except WebSocketDisconnect:
        manager.disconnect(websocket)
    except Exception as e:
        print(f"WebSocket error: {e}")
        manager.disconnect(websocket)


# Root endpoint
@app.get("/")
async def root():
    """API root endpoint."""
    return {
        "name": "Hermes Orchestrator API",
        "version": "1.0.0",
        "status": "running",
        "endpoints": {
            "health": "/health",
            "status": "/status",
            "tasks": "/tasks",
            "agents": "/agents",
            "knowledge": "/knowledge",
            "websocket": "/ws"
        }
    }


if __name__ == "__main__":
    uvicorn.run(
        app,
        host="0.0.0.0",
        port=8000,
        log_level="info"
    )
"}

